//! Copies the sound-port table generated by Nix into `OUT_DIR`.
//!
//! The table lives in `assets/audio-names.nix` and is generated by
//! `nix/scripts/gen-audio-names.py`. This build script does NOT generate it —
//! it only locates the finished file. Generating here would reimplement Nix
//! logic (invariant 5) and would leave the source of truth.
//!
//! The same shape as `ronoctua-bluetooth`'s build script, down to the reason
//! the destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_AUDIO_NAMES_RS");

    let generated = env::var("RONOCTUA_AUDIO_NAMES_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_AUDIO_NAMES_RS is not set.\n\
             \n\
             The sound-port table is generated by Nix out of\n\
             assets/audio-names.nix. Enter the environment with `direnv allow`\n\
             (or `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`.\n\
             \n\
             Generating the table here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("names.rs");
    // DELETE FIRST. The file comes from the store and carries its read-only
    // mode with it; on the second generation `fs::copy` would fail with
    // "Permission denied" inside a build script.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
